"use strict";(self.webpackChunktest_website=self.webpackChunktest_website||[]).push([[431057],{502790:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>i,default:()=>u,frontMatter:()=>s,metadata:()=>o,toc:()=>l});var o=n(554108),a=n(474848),r=n(28453);const s={tags:["UFO","2025-01"]},i="\u52d5\u753b\uff1aStanton Friedman \u306e \u66f8\u658e\uff0b\u8cc7\u6599\u5eab \u306e\u69d8\u5b50",h={authorsImageUrls:[]},l=[{value:"\u524d\u7f6e\u304d",id:"\u524d\u7f6e\u304d",level:2},{value:"\u8a72\u5f53\u7b87\u6240",id:"\u8a72\u5f53\u7b87\u6240",level:2},{value:"\u5207\u308a\u51fa\u3057\u9759\u6b62\u753b",id:"\u5207\u308a\u51fa\u3057\u9759\u6b62\u753b",level:2},{value:"FasterWhisper AI(large-v2 model) + DeepL(2024-07 model)",id:"fasterwhisper-ailarge-v2-model--deepl2024-07-model",level:2},{value:"Youtube \u52d5\u753b(49:48)",id:"youtube-\u52d5\u753b4948",level:2},{value:"\u304a\u307e\u3051\uff1a\u52d5\u753b\u5168\u4f53\u306e\u6587\u5b57\u8d77\u3053\u3057",id:"\u304a\u307e\u3051\u52d5\u753b\u5168\u4f53\u306e\u6587\u5b57\u8d77\u3053\u3057",level:2}];function d(e){const t={h2:"h2",hr:"hr",p:"p",...(0,r.R)(),...e.components},{Details:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)("a",{href:"/ds/img/gh_20250203_sf_2026.jpg",target:"_blank",children:(0,a.jsx)("img",{alt:"gh_20250203_sf_2026.jpg",border:"0",src:"/ds/img/gh_20250203_sf_2026.jpg",width:"90%"})}),"\n",(0,a.jsx)(t.h2,{id:"\u524d\u7f6e\u304d",children:"\u524d\u7f6e\u304d"}),"\n",(0,a.jsx)(t.p,{children:"\u898b\u304b\u3051\u305f\u306e\u3067\u8a18\u9332\u3057\u3066\u304a\u304f\u3002\u5730\u4e0b\u5ba4\u3092 \u66f8\u658e\uff0b\u8cc7\u6599\u5eab \u306b\u3057\u305f\u3088\u3046\u3060\uff08\u7a93\u304c\u7121\u3044\u304b\u3089\u6700\u521d\u306e\u7167\u660e\u306a\u3057\u306e\u30b7\u30fc\u30f3\u3067\u306f\u771f\u3063\u6697\uff09\u3002"}),"\n",(0,a.jsx)(t.p,{children:"\u3059\u3079\u3066\u5f7c\u3072\u3068\u308a\u3067\u5207\u308a\u56de\u3057\u3001\u79d8\u66f8\u306a\u3069\u306f\u3044\u306a\u3044\u3068\u3002"}),"\n",(0,a.jsx)(t.h2,{id:"\u8a72\u5f53\u7b87\u6240",children:"\u8a72\u5f53\u7b87\u6240"}),"\n",(0,a.jsx)(t.p,{children:"19:32--20:35"}),"\n",(0,a.jsx)(t.h2,{id:"\u5207\u308a\u51fa\u3057\u9759\u6b62\u753b",children:"\u5207\u308a\u51fa\u3057\u9759\u6b62\u753b"}),"\n",(0,a.jsx)("a",{href:"/ds/img/gh_20250203_sf_1941.jpg",target:"_blank",children:(0,a.jsx)("img",{alt:"gh_20250203_sf_1941.jpg",border:"0",src:"/ds/img/gh_20250203_sf_1941.jpg",width:"90%"})}),"\n",(0,a.jsx)("a",{href:"/ds/img/gh_20250203_sf_1953.jpg",target:"_blank",children:(0,a.jsx)("img",{alt:"gh_20250203_sf_1953.jpg",border:"0",src:"/ds/img/gh_20250203_sf_1953.jpg",width:"90%"})}),"\n",(0,a.jsx)("a",{href:"/ds/img/gh_20250203_sf_2013.jpg",target:"_blank",children:(0,a.jsx)("img",{alt:"gh_20250203_sf_2013.jpg",border:"0",src:"/ds/img/gh_20250203_sf_2013.jpg",width:"90%"})}),"\n",(0,a.jsx)(t.h2,{id:"fasterwhisper-ailarge-v2-model--deepl2024-07-model",children:"FasterWhisper AI(large-v2 model) + DeepL(2024-07 model)"}),"\n",(0,a.jsx)(t.p,{children:"\u8a00\u3046\u307e\u3067\u3082\u306a\u304f\u3001\u79c1\u306fUFO\u76ee\u6483\u8ac7\u3084\u7814\u7a76\u30d7\u30ed\u30b8\u30a7\u30af\u30c8\u3001\u63a8\u9032\u30b7\u30b9\u30c6\u30e0\u306b\u95a2\u3059\u308b\u30a2\u30a4\u30c7\u30a2\u306b\u3064\u3044\u3066\u591a\u304f\u306e\u4eba\u304b\u3089\u96fb\u8a71\u3092\u3082\u3089\u3046\u3002\r\n\u9762\u767d\u3044\u3053\u3068\u306b\u3001\u79c1\u304c\u81ea\u5206\u306e\u96fb\u8a71\u306b\u51fa\u308b\u3068\u3001\u307f\u3093\u306a\u9a5a\u304f\u3093\u3060\u3002\r\n(0:19:45)"}),"\n",(0,a.jsx)(t.p,{children:"\u79d8\u66f8\u3084\u540c\u597d\u306e\u58eb\u304c\u79c1\u306e\u305f\u3081\u306b\u50cd\u3044\u3066\u3044\u308b\u3068\u601d\u308f\u308c\u3066\u3044\u308b\u3002\r\n\u8ab0\u304c\u305d\u3093\u306a\u4f59\u88d5\u304c\u3042\u308b\uff1f\u79c1\u306f\u4e00\u4eba\u3067\u3084\u3063\u3066\u3044\u308b\u3002\r\n\u79c1\u304c\u81ea\u5206\u3067\u96fb\u8a71\u306b\u51fa\u308b\u3053\u3068\u306b\u9a5a\u304b\u308c\u308b\u3068\u3001\u3044\u3064\u3082\u9a5a\u3044\u3066\u3057\u307e\u3046\u3002\r\n\u3064\u307e\u308a\u3001\u4ed6\u306b\u8ab0\u304c\u79c1\u306e\u96fb\u8a71\u306b\u51fa\u308b\u3068\u3044\u3046\u306e\u3060\uff1f\r\n\u3067\u3082\u3001\u3067\u304d\u308b\u9650\u308a\u4eba\u306e\u5f79\u306b\u7acb\u3061\u305f\u3044\u3068\u601d\u3063\u3066\u3044\u308b\u3002\r\n\u53c2\u8003\u60c5\u5831\u304c\u5fc5\u8981\u306a\u3089\u3001\u5f7c\u3089\u306f\u3042\u3089\u3086\u308b\u3053\u3068\u3092\u77e5\u308a\u305f\u304c\u308b\u3002\r\n(0:20:10)"}),"\n",(0,a.jsx)(t.p,{children:"\u3053\u306e\u8fba\u308a\u306b\u306f\u305f\u304f\u3055\u3093\u306e\u7814\u7a76\u8cc7\u6599\u304c\u3042\u308b\u3002\r\n\u3060\u304b\u3089\u79c1\u306f\u3001\u6b63\u5f53\u306a\u76ee\u6a19\u3092\u6301\u3063\u3066\u3044\u308b\u3088\u3046\u306b\u898b\u3048\u308b\u4eba\u3001\u79c1\u306e\u7d4c\u6b74\u306a\u3069\u306b\u5408\u3063\u305f\u9069\u5207\u306a\u76ee\u6a19\u3092\u6301\u3063\u3066\u3044\u308b\u4eba\u3092\u52b1\u307e\u3059\u3088\u3046\u306b\u3057\u3066\u3044\u308b\u3002\r\n\u305d\u306e\u3044\u3044\u4f8b\u304c\u3001\u30af\u30ea\u30b9\u30fb\u30b9\u30bf\u30a4\u30eb\u30ba\u304c\u521d\u3081\u3066\u30b7\u30e3\u30b0\u30fb\u30cf\u30fc\u30d0\u30fc\u306e\u4ef6\u3067\u96fb\u8a71\u3092\u304f\u308c\u305f\u3068\u304d\u306e\u3053\u3068\u3060\u3002\u30af\u30ea\u30b9\u306f\u3061\u3087\u3046\u3069\u300e\u672a\u89e3\u6c7a\u30df\u30b9\u30c6\u30ea\u30fc\u300f\u306e\u30ed\u30ba\u30a6\u30a7\u30eb\u4e8b\u4ef6\u306e\u30b3\u30fc\u30ca\u30fc\u3092\u898b\u3066\u3044\u305f\u3068\u3053\u308d\u3060\u3063\u305f\u3002\r\n(0:20:37)"}),"\n",(0,a.jsx)(t.p,{children:"Needless to say, I get a lot of phone calls from people about UFO sightings, about research projects, about ideas on propulsion systems, and I try to be helpful.\r\nAnd it's funny, people are surprised when I answer my own phone, which I do when I'm home.\r\n(0:19:45)"}),"\n",(0,a.jsx)(t.p,{children:"They expect me to have a secretary and a whole coterie of people working for me.\r\nWho can afford it? I'm a one-man operation.\r\nI'm always surprised when people are surprised that I answer my own phone.\r\nI mean, who else is going to answer my phone?\r\nBut I try to help people whenever I can.\r\nIf they need reference information, they want to know all kinds of things.\r\n(0:20:10)"}),"\n",(0,a.jsx)(t.p,{children:"I've got a lot of research material around here, no question about that.\r\nSo I try to encourage those people who seem to have a justifiable goal, an appropriate one that fits in with my background and so forth.\r\nA good example is Chris Stiles, when he first called me about Shag Harbor. Chris had just been watching the Unsolved Mysteries segment on the Roswell incident.\r\n(0:20:37)"}),"\n",(0,a.jsx)(t.h2,{id:"youtube-\u52d5\u753b4948",children:"Youtube \u52d5\u753b(49:48)"}),"\n",(0,a.jsx)(t.p,{children:"UFOs - The Stanton Friedman Story"}),"\n",(0,a.jsx)(t.h2,{id:"\u304a\u307e\u3051\u52d5\u753b\u5168\u4f53\u306e\u6587\u5b57\u8d77\u3053\u3057",children:"\u304a\u307e\u3051\uff1a\u52d5\u753b\u5168\u4f53\u306e\u6587\u5b57\u8d77\u3053\u3057"}),"\n",(0,a.jsxs)(n,{children:[(0,a.jsx)("summary",{children:"\u25bc\u539f\u6587 \u5c55\u958b"}),(0,a.jsx)(t.p,{children:"First the question, are there any flying saucers?\r\nNow, some people get very angry at me for using the word flying saucers.\r\nWhy don't you say UFOs, Stan?\r\nFlying saucers, that's a tabloid bit of nomenclature. That's not so.\r\nI want to make a very clear-cut distinction between flying saucers and UFOs. All flying saucers are unidentified flying objects.\r\nVery few unidentified flying objects are flying saucers.\r\n(0:01:31)"}),(0,a.jsx)(t.p,{children:"And besides, UFOs didn't come into use until after 1950, and I'm interested especially in what happened in 1947, when it was flying saucers, flying disks.\r\nThere's nothing wrong with the term.\r\nSo don't get mad at me for using the word.\r\nI've used it for many years. My lecture is normally, flying saucers are real, and I'm not ashamed of it at all.\r\nNext speaker is Stan T. Friedman, known as the flying saucer physicist, nuclear physicist by background, a noted author, and one of our long-time supporters.\r\n(0:02:17)"}),(0,a.jsx)(t.p,{children:"I'm cute. I've spoken at more MUFON conferences than anybody.\r\nThat's because I'm older than most of the guys up here.\r\nWorked in industry on more canceled government-sponsored advanced research and development programs than anybody that I've ever met.\r\nNuclear airplanes, fission and fusion rockets, nuclear power plants for space, little companies like General Electric, Westinghouse, General Motors, TRW System, McDonnell Douglas. I've focused particularly on the Roswell incident.\r\n(0:02:46)"}),(0,a.jsx)(t.p,{children:"Somebody called me the grandfather of Roswell. It used to be the father of Roswell, but I guess I'm getting older.\r\nI get around. Noisy, that's what I am.\r\nI talk about noisy negativists. I'm a noisy positivist.\r\nMr. Friedman has spoken at more than 600 colleges and over 100 professional groups in the 50 states, 9 Canadian provinces, and 13 countries.\r\nHe's published over 70 UFO articles, co-authored the book Crash at Corona, the Definitive Study of the Roswell Incident, his 1996 book about the Operation Majestic 12 Top Secret Magic is in its 6th printing.\r\n(0:03:27)"}),(0,a.jsx)(t.p,{children:"The title of Mr. Friedman's program is Flying Saucers and the Cosmic Neighborhood, and he'll be looking at just where these folks might be coming from.\r\nStan?\r\nThe more lecturing I did, the more I realized that I really enjoyed being on the stage.\r\nThe bigger the crowd, the happier I was.\r\nAnd secondly, I found that I like people.\r\nI stand behind a table with information sheets, with books and stuff.\r\n(0:03:54)"}),(0,a.jsx)(t.p,{children:"People are always wanting to tell me about their experiences.\r\nThere's no question that some people think, well, maybe that was a flying saucer, and they sent all these shells.\r\nI saw it go across the sky.\r\nOh, you did see the thing in the sky?\r\nOh, sure. From Southgate, it was about this level.\r\nThe thing that hit me is when you came to the part in your film, I mean, in your video, in reference to the smoke round, or whatever it's called.\r\n(0:04:23)"}),(0,a.jsx)(t.p,{children:"The ionized air plasma round.\r\nYeah. Well, it was something like this.\r\nEven though they don't provide classified documentation, when the seemingly respectable people, independently, all over the world, tell me the same kinds of stories, I can't dismiss it.\r\n(0:04:42)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"So you get a hand, your finger on the pulse of what's going on when you do enough lectures in enough places.\r\nAnd because I come on so strong, they know I'm not going to laugh at them.\r\nLet's get rid of another myth.\r\nThere are too darn many apologist ufologists.\r\nBecause many people on both sides of the aisle, so to speak, have accepted the notion that most people don't believe in flying saucers.\r\n(0:05:10)"}),(0,a.jsx)(t.p,{children:"I have no idea why.\r\nI've had 11 hecklers in over 700 lectures.\r\nAnd two of them were drunk.\r\nYou're going to get that many if you talk about religion, sports, politics.\r\nThere's no big risk here in sticking your neck out.\r\nBut people's actions are determined by their perception of what other people are going to say in response to what they say.\r\nIt's okay.\r\n(0:05:34)"}),(0,a.jsx)(t.p,{children:"Here's several Gallup polls.\r\nThey show not only that believers outnumber non-believers, the real over the imaginary, but that the greater the education, the more likely to believe in flying saucers.\r\nThat comes as a real shocker.\r\nWe in MUFON have our UFO evangelists.\r\nStan Freedman is my favorite UFO evangelist.\r\nWhen Dwight Connolly did his MUFON UFO Journal profile on Stan, his title was, Stanton Freedman Spreads the Word. Stan would make a great Jewish UFO Presbyterian preacher.\r\n(0:06:15)"}),(0,a.jsx)(t.p,{children:"An idea which newspaper people and Alan Hynek would say has a high degree of strangeness.\r\nI was born in Elizabeth, New Jersey, in 1934 at the height of the Depression. My dad was born in Chicago. His parents came over from Lithuania about 1900, 1901. My mother, her parents came from the Ukraine, near Kiev, around 1902, 1903. I grew up in Linden, New Jersey. First 19 years of my life.\r\n(0:06:59)"}),(0,a.jsx)(t.p,{children:"It was a working man's town.\r\nLots of immigrants to do the dirty jobs at the factories.\r\nBut back in the 30s, if you got a job, you were lucky.\r\nMy dad stayed with American Cyanamid for 37 years.\r\nI've been asked what it is that drives me to go after the details, the minutia, to try to get things straight.\r\nAnd the best explanation I can come up with is something that happened in the fifth grade, if you would believe.\r\n(0:07:26)"}),(0,a.jsx)(t.p,{children:"I was a straight-A student as a kid, and I was in the fifth grade, and Miss Gutkin, our teacher, Rose Gutkin, one day in class, she was talking about astronomy, and maybe it was under the heading of science, I suppose.\r\nShe said, the sun stands still, and the Earth and the other planets move around the sun.\r\nWell, that hit me the wrong way, because I had just the day before read in our new encyclopedia volume.\r\n(0:07:55)"}),(0,a.jsx)(t.p,{children:"You bought one volume at a time at the supermarket for 29 cents.\r\nI said, no, Miss Gutkin, the whole solar system is moving around the center of the galaxy.\r\nWell, she dressed me down in front of the other students.\r\nNo, that's not right, Stan. That's not right at all.\r\n(0:08:15)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"And she went on for a little bit.\r\nNow, I didn't say anything back.\r\nI never sassed the teacher.\r\nBut I was hurting inside.\r\nI didn't much appreciate that when I was sure that's what I had read the day before, no less.\r\nSo, naturally, I went home and got the encyclopedia and brought it in the next day.\r\nAnd she read it.\r\nAnd she very reluctantly admitted, well, maybe that's the way it really was.\r\n(0:08:41)"}),(0,a.jsx)(t.p,{children:"Now, she didn't apologize for dressing me down.\r\nBut I felt vindicated.\r\nBut I also felt I learned a lesson.\r\nIf I didn't want to be dressed down by people, I'd better have my facts in hand before I open my mouth.\r\nThat may be one of the reasons I went into debating in high school.\r\nI certainly didn't realize it at the time, but my high school career, four years at Linden High School in Linden, New Jersey, did prepare me for my activities as a UFO investigator, as a lecturer, as somebody defending truth and liberty and all that stuff.\r\n(0:09:17)"}),(0,a.jsx)(t.p,{children:"I was on the debate team my freshman, sophomore, and junior years.\r\nWe won a state championship.\r\nAnd one thing about debating, you have to learn to handle both sides of the argument, because you never know which way you're going to go when the tournaments come up.\r\nAnd also, you have to get your facts straight.\r\nYou can't make up things.\r\nIt's sort of against the rules.\r\n(0:09:37)"}),(0,a.jsx)(t.p,{children:"But we didn't have a debate team in my senior year.\r\nAnd instead, I got into drama.\r\nI was in two plays in my senior year.\r\nI played a priest in a play, The Valiant Never Taste of Death But Once. I remember the line.\r\nAnd I got a real kick.\r\nAnd on one application for college, I remember they asked, What did you enjoy most in high school?\r\n(0:10:01)"}),(0,a.jsx)(t.p,{children:"And I'd done a lot.\r\nBut I put down being in those two plays, and that was far more prophetic than I ever expected.\r\nNow, if you'd told me that I'd wind up spending my life lecturing about flying saucers, I'd have laughed my head off.\r\nI received my master's degree in physics from the University of Chicago in 1956. Two years later, in 1958, I was working as a nuclear physicist for the General Electric Aircraft Nuclear Propulsion Department near Cincinnati. I was ordering books from a mail-order place in New York and needed one more book so I wouldn't have to pay shipping.\r\n(0:10:36)"}),(0,a.jsx)(t.p,{children:"And there was one, The Report on Unidentified Flying Objects by United States Air Force Captain Edward Ruppelt. And then I stumbled across Project Blue Book, Special Report No. 14, in about 1960 at the University of California, Berkeley Library. And I was astonished because it hadn't been mentioned in any of the 15 books that I had read.\r\nAnd it not only provided me with tons of data, and I'm a data hound, I'll admit it, information on 3,200 sightings, 240 charts, tables, graphs, maps, data heaven.\r\n(0:11:09)"}),(0,a.jsx)(t.p,{children:"But it also had the press release that the Air Force issued when the document was sort of released.\r\n(0:11:15)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"It wasn't distributed, but they put out a huge press release all over the country.\r\nAnd that shocked me because it proved, once you looked at the data, as I had been, that the Air Force was lying about the results of their study.\r\nAnd what's interesting is that nobody in the press made an effort, apparently, judging by the articles I've seen, to get to the truth of the matter.\r\n(0:11:37)"}),(0,a.jsx)(t.p,{children:"They were buying what the Secretary of the Air Force said, and that's terribly sad.\r\nAnd you know what?\r\nThey're still buying what lies are being told by the Air Force. And that's really sad.\r\nI was working on classified programs.\r\nI understand national security and how it works and so forth.\r\nBut they were outright lying.\r\nThat got my dander up.\r\nI later visited Project Blue Book many times.\r\n(0:12:06)"}),(0,a.jsx)(t.p,{children:"But that really began a 40-year quest now for the truth about flying saucers.\r\nI think I've found it.\r\nThe Secretary of the Air Force, about this study, this is what the public heard all over the country, all over the world.\r\nWe believe that no object such as those popularly described as flying saucers have overflown the United States. Even the unknown 3% could have been identified as conventional phenomena or illusions if more complete observational data had been available.\r\n(0:12:41)"}),(0,a.jsx)(t.p,{children:"The problem is that the two factual statements in the Air Force Secretary's summary are both false.\r\nThe unknowns were not 3%, and they were not the sightings for which there wasn't enough information.\r\nI did a lot of reading, and when I had moved to Indianapolis, I got to know Frank Edwards, who was quite a UFO researcher.\r\nAnd when he came out with his new book, Flying Saucers' Serious Business, which became a bestseller, he sent me a copy in Pittsburgh, where I was now working for Westinghouse Astronuclear Laboratory on nuclear rockets.\r\n(0:13:16)"}),(0,a.jsx)(t.p,{children:"Read the book, decided I ought to do something, called Frank, he named some people I should talk to.\r\nOne of them was a radio station in Pittsburgh, KDKA, one of the earliest big radio stations.\r\nI called them, they said, don't call us, we'll call you for a talk show.\r\nSomebody cancelled out at the last minute they called me, because I lived near the station.\r\n(0:13:35)"}),(0,a.jsx)(t.p,{children:"Somebody at work heard me, and asked me to speak to their book review club, because they were looking at Frank Edwards' book.\r\nAnd I did, that was my first lecture in somebody's living room.\r\nThe first big college lecture was at Carnegie Mellon University there in Pittsburgh, and only because I knew the wife of the guy who was the dean, and he booked me, and asked me how much I wanted, I figured I'd have to take half a day off work, it was a morning lecture.\r\n(0:14:03)"}),(0,a.jsx)(t.p,{children:"I said $100, thinking he'd cut me down to $50. He said sold, then he told me what he was paying the other people, $1,200, $1,500, and that led me to believe that I could make some money, perhaps enough to support a family giving lectures.\r\n(0:14:19)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"So when the bottom fell out of the advanced nuclear and space systems business, as it finally did in 1969, 1970, I went full-time lecturing.\r\n3,201 site, that's a pretty good number.\r\nProject, a blue book, special report number 14. Now look at all the categories here, miscellaneous covered a whole long list of things.\r\nThis is really psychological aberrations, a very polite way of saying crackpot cases.\r\n(0:14:48)"}),(0,a.jsx)(t.p,{children:"You'll notice that those were 1.5%. 2% of the papers submitted to the American Physical Society by physicists are crackpot papers, they say.\r\nI think that means there are more crackpots associated with physics than with flying saucers.\r\nI like to use humor in my lectures, usually to poke fun at the nasty, noisy negativists, to show things in a sort of ridiculous light on occasion as required.\r\n(0:15:15)"}),(0,a.jsx)(t.p,{children:"I don't go out and tell jokes. I'm not any young man.\r\nBut I try to soften up the audience and for once get them laughing at the nasty, noisy negativists instead of those of us who are convinced that some UFOs are alien spacecraft.\r\nOh, another group that doesn't want flying saucers to be real are the SETI cultists.\r\nS-E-T-I, silly effort to investigate.\r\nA cult is a group of people who have a strong dogma, charismatic leadership, strong resistance to outside voices, and boy, the SETI guys sure show that in spades.\r\n(0:15:52)"}),(0,a.jsx)(t.p,{children:"They don't want it to be real because who needs a radio telescope?\r\nThere's real job security. Hello out there!\r\nYou know, 40 years later, hi there, what can we do for you?\r\nYou pass the job on to your kids.\r\nThey have no evidence. We got loads of it.\r\nBut they say we're being unscientific, and they're being scientific.\r\nHe backs up what he's saying with, you know, facts.\r\n(0:16:19)"}),(0,a.jsx)(t.p,{children:"Like, he talks about, you know, the skeptics, you know, how they just believe because that's what they believe. They don't go to the facts.\r\nIf you go to the facts, you know, the evidence is overwhelming, pointing towards, you know, the existence of some UFOs are extraterrestrials.\r\nStan was a great representative, especially to somebody like myself who hasn't really been in the UFO community, you know, maybe from the outside you would think that this field is with a lot of sort of strange people or whatever, but Stan is extremely intelligent and articulate, and I thought it was very interesting what he had to say.\r\n(0:16:57)"}),(0,a.jsx)(t.p,{children:"The arrogance of each generation of ancient academics and fossilized physicists is something to behold.\r\nWell, I'm trying to encourage the young people, you should respect your elders, but check and double-check and triple-check the assumptions that they're making to come to the conclusion that there isn't anything new, because there is and there always will be.\r\nIf you get younger people, that's what you need.\r\n(0:17:24)"}),(0,a.jsx)(t.p,{children:"You know, what's his name, Max Planck said, new ideas come to be accepted not because their opponents come to believe in them, but because their opponents die and a new generation grows up that's accustomed to them.\r\n(0:17:36)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"It's true.\r\nOne thing about the life I've been leading for the last 30-some years, in terms of almost full-time lecturing, is that the travel can be rugged.\r\nNow, some people say, oh, you travel all these exotic places, it must be great fun.\r\nFrankly, it's work.\r\nMy longest tour was 25 lectures in 15 states in 35 days.\r\nAnd believe me, that was work.\r\nI watched spring come in in three different parts of the United States. And the thing is, I don't just lecture, but I do classroom visits, I do seminars, I do interviews.\r\n(0:18:20)"}),(0,a.jsx)(t.p,{children:"I've started some days at 8 in the morning, done five classes in a row, done three interviews, give a lecture that night, talk for an hour and a half, answer questions until the janitor kicks us out of the hall, go back to the motel by myself, get up in the morning and catch a plane at 6.30 or 7. That's work.\r\nAnd usually I don't get a chance to see much of the towns I visit.\r\n(0:18:44)"}),(0,a.jsx)(t.p,{children:"Every once in a while there's an extra day because I'm on the way to someplace else in a day or two, where I do get a chance to look at things, but it can be lonely.\r\nIt's amazing to me that he's been so persistent, staying with the task, which has been so frustrating.\r\nThe work he's done in the Roswell case has required a tremendous amount of travel and investigation and going through records in which you get almost no results for a long time, and then you finally get one little clue, and you try to get more information to back it up.\r\n(0:19:17)"}),(0,a.jsx)(t.p,{children:"And the energy it takes and the hope and the sustenance to keep going, that he has this energy to do this, just amazes me.\r\nNeedless to say, I get a lot of phone calls from people about UFO sightings, about research projects, about ideas on propulsion systems, and I try to be helpful.\r\nAnd it's funny, people are surprised when I answer my own phone, which I do when I'm home.\r\n(0:19:45)"}),(0,a.jsx)(t.p,{children:"They expect me to have a secretary and a whole coterie of people working for me.\r\nWho can afford it? I'm a one-man operation.\r\nI'm always surprised when people are surprised that I answer my own phone.\r\nI mean, who else is going to answer my phone?\r\nBut I try to help people whenever I can.\r\nIf they need reference information, they want to know all kinds of things.\r\n(0:20:10)"}),(0,a.jsx)(t.p,{children:"I've got a lot of research material around here, no question about that.\r\nSo I try to encourage those people who seem to have a justifiable goal, an appropriate one that fits in with my background and so forth.\r\nA good example is Chris Stiles, when he first called me about Shag Harbor. Chris had just been watching the Unsolved Mysteries segment on the Roswell incident.\r\n(0:20:37)"}),(0,a.jsx)(t.p,{children:"And Stanton, of course, being the expert on it at the time, was on the program, and Chris thought, well, I'll try.\r\n(0:20:47)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"And he looked up his phone number, surprised to learn that he lived in Fredericton, New Brunswick, and transplanted American. And he called there, he got forwarded through to a motel in Dallas, Texas, because that's where Stanton was doing a lecture at the time, I guess.\r\nAnd talked to Stanton, and Stanton sort of gave him some leads about where he should start looking.\r\nAnd I guess we owe Stan the opening part of our investigation on how to get going on this thing, you know, with Chris and so on.\r\n(0:21:18)"}),(0,a.jsx)(t.p,{children:"Yeah, I find Stan to be a very tenacious researcher.\r\nHe seems to be tireless in his research.\r\nHe'll follow leads to the very end and try to squeeze every bit of information that he can out of it.\r\nUFOs are a thing that's very difficult to be purely scientific about.\r\nIf your version of scientific is, when you haul me a dead alien in front of me, I'll believe, you know, you may not bother with the UFO field very much.\r\n(0:21:47)"}),(0,a.jsx)(t.p,{children:"And so Stan has had to be satisfied with evidence, but not foolproof, in order to keep going, and he's done that very well.\r\nAs a scientist himself, he's gone out there and put his professional career on the line years and years and years ago and went out there and said, you know, this is happening.\r\nI believe in the extraterrestrial hypothesis.\r\nThese things are intelligently controlled and they're not from here.\r\n(0:22:12)"}),(0,a.jsx)(t.p,{children:"And he makes no bones about that.\r\nAnd he's been carrying that around on his shoulders and bearing a great deal of burden, I think, because of that.\r\nAnd you've got to respect a guy that gets out there and does that and yet backs it up with his scientific credibility.\r\nI think that he is careful in his scientific analysis.\r\nAt the same time, he's not slow to offer opinions.\r\n(0:22:40)"}),(0,a.jsx)(t.p,{children:"Some scientists won't give you their opinions.\r\nStan's more than willing to give you his opinions.\r\nWhen somebody tells you the only sightings that couldn't be explained are poor quality sightings by incompetent observer, they are not telling the truth.\r\nThey should not be allowed to proceed without justifying that statement.\r\nAnd they can't because it isn't true.\r\nStan Friedman was very much a major contributor to some really very, very important... and contributed very, very important work to that kind of what you would think of as scientific ufology.\r\n(0:23:18)"}),(0,a.jsx)(t.p,{children:"Let's look at the phenomenon. What does the data tell us?\r\nWhat can we learn from this about our visitors, if there are visitors, and where they come from?\r\nAs time went by, as Roswell came to the fore, as the abductions came to the fore, we found ourselves more and more focused on government cover-up and conspiracy and less on what the government was covering up and conspiring about.\r\n(0:23:45)"}),(0,a.jsx)(t.p,{children:"That is, the UFO phenomenon and the data about it.\r\nAnd Stan moved into that... into that realm with a vengeance, with Roswell. And he spent the past, you know, 20 years now really focused on things like MJ-12 and government conspiracy and all of that, and has done very little, sadly, on the kind of things that he was working on in the past.\r\n(0:24:15)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"We're dealing with the biggest story of the millennium.\r\nVisits to planet Earth by alien spacecraft, successful cover-up of the best data, bodies in wreckage, for 54 years.\r\nWhy don't we know more?\r\nIt's the failure of the scientific and journalistic communities are the two major things.\r\nAnd, of course, those other forces that don't want us to know about globalization and being an Earthling and alien visitors.\r\n(0:24:45)"}),(0,a.jsx)(t.p,{children:"Lots of those forces.\r\nOne of the issues that's very prevalent in the UFO community is the conspiracy issue.\r\nGranted, government does not release all information, but I also know from my own experience in the military that the government can't keep secrets very well.\r\nUltimately, the stuff leaks out.\r\nMaybe not the documents, but ultimately it does leak out.\r\nAnd to this date, there's been no real smoking gun that's come out of the information that has been released or that's been supposedly overheard by people that would dispel my beliefs that it's anything but a misinterpreted event.\r\n(0:25:27)"}),(0,a.jsx)(t.p,{children:"It took me five years to get one of the important CIA UFO documents.\r\nI want to show that to you, so you'll see how much we learned from those documents.\r\nYeah, there's five years to get that.\r\nWell, it's got a lot of information.\r\nIt says title, doc reference, info date, string of numbers, USSR, and more numbers, and that's it.\r\nThey're not holding back anything.\r\n(0:25:58)"}),(0,a.jsx)(t.p,{children:"Now, how could you accuse the government of keeping a secret from us?\r\nStan is famous for flipping the blacked-out pages and said, you know, what's going on here?\r\nWell, we now know that the reason they covered that up was not because there was UFO information in it, but because there was critical source information in it.\r\nThe Soviets may determine, based on some of the stuff released in that report, where the information was gathered, and it could adversely affect the person who helped in the gathering of the information.\r\n(0:26:32)"}),(0,a.jsx)(t.p,{children:"I don't know how much of this is a consequence of frustration after years and years and years of trying to tease out the answers from the data in hand, and how much of it is a genuine belief that if we crack this cover-up, we're going to have all the answers, so let's not waste any more time poking around with the data and doing all that rather boring hard work.\r\n(0:27:06)"}),(0,a.jsx)(t.p,{children:"I just, that I don't know.\r\nI suppose, in some ways, it's also more exciting if you're thinking in terms of cover-up. You know, I mean, there's a kind of, you know, James Bond-ish, X-file-ish kind of aspect to it that makes it more fun.\r\nI met somebody once who let me in on a little secret.\r\nHe had worked at the White House. He was a professional person, and he had access to all kinds of stuff which he saw about flying saucers.\r\n(0:27:38)"}),(0,a.jsx)(t.p,{children:"And he told me, you know, they kill people for leaking stuff like that.\r\nAnd I believe him.\r\nBut I can't live my life worrying about what the government's going to do and looking over my shoulder.\r\n(0:27:52)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"I have made seven trips in the last three years to Roswell. It's a 200-mile drive from Albuquerque to Roswell, and there's nobody there.\r\nLots of nothing in New Mexico. And I give out my itinerary, I tell my answering service, tell people where I am and where I'll be going and all this kind of stuff.\r\nIf anybody wanted to take me out, I had ample opportunity.\r\n(0:28:14)"}),(0,a.jsx)(t.p,{children:"If you're thinking in terms of government cover-up and conspiracy and intimidation of witnesses and all of that, that tends to validate your own importance, too.\r\nBecause they care about what we're doing.\r\nIf you don't have that kind of attention from them, then who are you but just another bunch of folks that are interested in something that's slightly off the wall?\r\nNow, these guys got a sense of humor.\r\n(0:28:41)"}),(0,a.jsx)(t.p,{children:"This page says, Deny in Toto. They couldn't find eight lousy words to declassify.\r\nOf course there's a cosmic water gate.\r\nThis is just the tip of the iceberg.\r\nThere's no case that better illustrates that than the Roswell case.\r\nI knew that was important when I began the civilian investigation of it back in the 70s. I had no idea how important.\r\nI do now.\r\n(0:29:15)"}),(0,a.jsx)(t.p,{children:"And you've got evidence that the government recovered not only a crash-flying saucer or two, but alien bodies.\r\nAnd they set up an outstanding group of people to deal with that information and have kept it secret all these years.\r\nThat's definitely a cosmic water gate.\r\nRoswell is important because it defines ufology, both when it first happened in 1947, but also the rediscovery.\r\nIt tells us a great deal about the hidden nature of the UFO phenomenon and why it has been buried for so long.\r\n(0:29:51)"}),(0,a.jsx)(t.p,{children:"Once we understand Roswell, once we understand what happened at Roswell, we understand why ufology developed the direction it developed for the next 50 or 60 years.\r\nWe understand what is going on.\r\nWe understand that there was a necessity for hiding a great deal of UFO information.\r\nAnd if Roswell had not happened in 1947, the whole history of ufology would have been different.\r\nStan Friedman has devoted much of his life to attempting to establish a factual basis, an evidential basis, for accepting his view of what happened in 1947. He was the first, really, beginning in 1978, to interview Jesse Marcel in a systematic way.\r\n(0:30:42)"}),(0,a.jsx)(t.p,{children:"He was the premier pioneer in constructing the Roswell myth.\r\nAnd in doing so, he has become very comfortable in a certain vocabulary, in a certain way of talking about things, in a certain assurance about the sources and the like, so that he feels that his worldview, his particular point of view with respect to Roswell, is true.\r\nThe poster on the wall in Fox Mulder's office that says, I want to believe, is a representation of what happens to be the very real thing in ufology.\r\n(0:31:26)"}),(0,a.jsx)(t.p,{children:"People want very much to believe whatever it is that happens to be their interest.\r\n(0:31:32)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"Aliens' visitation, abductions, etc.\r\nAnd unfortunately, what happens is that this leads them to ignore facts that are inconvenient, that is, facts which are contrary to the things that they want to believe.\r\nRoswell is replete with this.\r\nFriedman is something of a romantic who is interested in good stories and in trying to explain what otherwise would remain mysteries.\r\nIn the process of doing so, he and his colleagues have constructed, really, a marvelous story.\r\n(0:32:15)"}),(0,a.jsx)(t.p,{children:"It's a story of momentous happenings, of mysterious occurrences, of good guys and bad guys, and it has a transcendental message that we are not alone in the universe.\r\nIt's very interesting to see what has transpired in Roswell itself and what the town has done with the celebrity that has come with Roswell, the flying saucer crane.\r\nFor a long time, there was a good deal of resistance in town to the idea that they should in any way try to exploit it or take advantage of it.\r\n(0:32:55)"}),(0,a.jsx)(t.p,{children:"But Max Littel and Glenn Dennis and Walter Haught, three founders of the International UFO Museum and Research Center in Roswell, pressed ahead anyway.\r\nAnd over time, people began to realize that this was an opportunity to have people not only come or pass through Roswell on their way to Carlsbad Caverns and the like, but to stick around for a couple of days.\r\nI've been to Fatima and Lourdes and to Jerusalem and to one of the great shrines of the Lord Shiva in Nepal. I prefer what I saw in Roswell. I was in Lourdes during the festival of the Assumption of the Virgin. It was very impressive and hypnotic, really.\r\n(0:33:48)"}),(0,a.jsx)(t.p,{children:"But I didn't have anywhere near as much fun as I did in Roswell. One of the things that constantly happened in Roswell was people would turn to us and a constant theme, a constant question that was being asked again and again was, Do you believe? Are you a believer?\r\nPeople would introduce, I'm high on so-and-so from Duluth. Are you a believer?\r\nAnd many, many people replied, Yes, I'm a believer.\r\n(0:34:20)"}),(0,a.jsx)(t.p,{children:"When we started on this idea of having a UFO museum, Stan Friedman was the first one that helped us out.\r\nHe still helps us out.\r\nHe's been so involved in so many different places that his knowledge is so far beyond ours here that we couldn't operate without him.\r\nAnd I hate to pat him on the back too much, but it has been something that has been of an absolute big operation.\r\n(0:35:02)"}),(0,a.jsx)(t.p,{children:"Everything that we've done, he's been in there and told us, Do it this way. Do it this way.\r\nAnd it's worked out just beautifully.\r\nI think this kind of dishonest representation of all this material, bogus and otherwise, by Roswell, further brings down the field of serious UFO research.\r\nBecause, again, it's one of those things that defines what UFOs are all about in people's minds.\r\n(0:35:41)"}),(0,a.jsx)(t.p,{children:"It's making money, it's a sideshow, it's parades and carnivals and fun and silliness.\r\n(0:35:50)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"Not something serious.\r\nAnd to that extent, the skeptics are right.\r\nI mean, UFOlogy, unfortunately, is caught up in this kind of stuff.\r\nAnd this is probably one of the more dramatic examples of it.\r\nI was on a television program once, a town meeting, Sunday afternoon.\r\nEvery Sunday, this was out in Portland, Oregon. Every Sunday they asked people to phone in yes or no to a question.\r\n(0:36:16)"}),(0,a.jsx)(t.p,{children:"This week the question was, Do you think the government's told us all it knows about flying saucers?\r\nAnd I was in the hot seat and they'd gone down to Roswell and so forth.\r\n3,900 people called.\r\n92% said no, they don't think the government's told us all it knows about flying saucers.\r\nThat's a pretty big lack of confidence.\r\nAnd they couldn't all have been just UFO believers, if you will.\r\n(0:36:42)"}),(0,a.jsx)(t.p,{children:"I hate that term, but I'm stuck with using it.\r\nYou know what I mean when I say it.\r\nSo, yes, there is a pop culture side to all of this.\r\nOne reason, incidentally, is a peculiar one.\r\nWhen I asked the people at the gift shop at the Roswell International UFO Museum and Research Center... There are a lot of places where you can buy alien-oriented stuff.\r\n(0:37:04)"}),(0,a.jsx)(t.p,{children:"You know, T-shirts and all the rest.\r\nOh, all over the place.\r\nMany, many companies.\r\nWell, one reason is you don't need to pay royalties to anybody.\r\nAt least the aliens haven't billed anybody for using their likeness.\r\nSo there's an interaction here.\r\nPop culture tends to follow reality.\r\nRoswell gives it a face, a focus.\r\nThe real problem I have is that time after time, these people have received so-called anonymous documents, anonymous letters, signed by individuals who asked that their name not be released or not signed at all.\r\n(0:37:51)"}),(0,a.jsx)(t.p,{children:"And they're using this as evidence to substantiate their claim.\r\nAnd that's a foolish way to do things.\r\nYou know, that wouldn't go anywhere in a courtroom.\r\nYou know, the court wouldn't even allow that kind of testimony.\r\nIt's absurd.\r\nAnd yet, you know, I do wonder why people fall victim to these claims.\r\nYou know, why does a person of high academic standing step over the itch?\r\n(0:38:17)"}),(0,a.jsx)(t.p,{children:"And I've also worked, oh yes, on the MJ-12 documents.\r\nThere's a display about them back there.\r\nMost important classified government documents ever leaked to the public.\r\nThey tell the story of the establishment by President Truman of a group of 12, an all-star cast of people, whose job it was to deal with the recovery of the crash saucer at Roswell. And there were an all-star cast, the first three directors of Central Intelligence, the first Secretary of Defense, six outstanding scientists.\r\n(0:38:53)"}),(0,a.jsx)(t.p,{children:"Well, after 11 years and visits then to 15 archives, I've been to 19 now, and I'm convinced the documents are real.\r\nOnce you have committed yourself to a particular theory or a particular set of, in this case, like Roswell, documents backing up the case and so on, it's extremely difficult.\r\n(0:39:14)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"Once you've not only committed yourself to them, but you've done so publicly that you have established a reputation on, and that you've written about at length, that you've published books about, etc., it's extremely difficult to stand up and say, whoops, I was wrong.\r\nI believe that it was perfectly natural to suggest that the United States government set up a super-secret project similar to the Manhattan Project. Many different people, many different places, many different functions.\r\n(0:39:45)"}),(0,a.jsx)(t.p,{children:"Now, that was a thought.\r\nWell, in 1984, I was working with William Moore and Jamie Shandoray. They were still in California. I had moved from California to New Brunswick in 1980. I got a call from Bill that they had received a roll of film in the mail.\r\nOn this roll of film, there were two sets of eight negatives each of a top-secret-slash-magic-eyes-only document.\r\n(0:40:17)"}),(0,a.jsx)(t.p,{children:"One of the peculiar aspects of the document was that it named somebody Dr. Donald Howard Menzel, a Harvard University professor of astronomy, as a member of the group.\r\nAnd my first thought, Bill read me the list on the phone.\r\nThis is December 1984. And my first thought was, oh, somebody's pulling our leg.\r\nDr. Menzel was the Phil Class of his day, if you will.\r\n(0:40:44)"}),(0,a.jsx)(t.p,{children:"He was the champion debunker of UFOs during the 50s and 60s. He was a Harvard astronomer, very highly respected.\r\nAbsolutely rabid anti-UFO debunker.\r\nAnyway, he's included as a member of MJ-12, which, of course, many people said, well, you know, that doesn't make any sense. Why would this debunker be a member of this?\r\nWell, Stan started digging, discovered that Menzel had this history of working for the National Security Agency as a cryptanalyst and so on, and decided, well, this shows that he had this secret life, and that his debunking was simply, it may have been part of the disinformation campaign of MJ-12, or it was a cover for Menzel's real role, etc.\r\n(0:41:33)"}),(0,a.jsx)(t.p,{children:"But when you look at Menzel's history, it's clear that this is, you know, nothing that he did in the intelligence field had anything to do with UFOs. He was a cryptographer, taught courses on cryptography, code-breaking and stuff.\r\nTurned out he'd learned Japanese, which helped in the code-breaking. It turned out he did classified work for more than 30 companies.\r\nIt turned out he had a top-secret ultra-clearance with the U.S. Navy and with the CIA. The particularly interesting angle is this.\r\n(0:42:05)"}),(0,a.jsx)(t.p,{children:"Menzel had a thing for mythical Martians. He doodled them, he made Christmas cards with mythical Martian scenes and funny little Martians running about, he made paintings of Martians. My friend Jim Mosley, the editor of Saucer Smear, has one signed to him by Menzel, of this scene of Buxom Martian maidens cavorting about the canals of Mars, etc.\r\nAnyhow, in the MJ-12 documents, we have Dr. Menzel cited as being the one person who strongly argues that the saucers are not from the planet Mars. I think that that was a kind of inside joke.\r\n(0:42:46)"}),(0,a.jsx)(t.p,{children:"And I think the joke turned out to be on Stan Freedman. My opinion on Majestic-12 is the documents were created in the UFO community to propel specific people into the spotlight.\r\n(0:42:58)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"And I have said repeatedly and I'll say again, Stan Freedman is not a participant in the hoax.\r\nHe is merely one of those who have been unfortunately caught up in the hoax and become a proponent of it, but he is not a participant in the hoax.\r\nThe MJ-12 documents, as well as an allegedly supporting memorandum, the Cutler-Twining Memorandum, which was found, in quotes, found at the National Archives by Jamie Chandra and Bill Moore, all of these things have one thing in common, that's Bill Moore. They all surfaced in one way or another through Bill Moore. Do I think there's any chance that Bill faked the documents? No. He didn't know enough of the minutia to get all those things right.\r\n(0:43:45)"}),(0,a.jsx)(t.p,{children:"Yes, it's easy to say, Bill was tricky, he did some strange things on occasion, but that doesn't mean he faked the documents.\r\nThat which you want to believe, Francis Bacon said this, that which you want to believe, you more readily believe to be true.\r\nAnd so anything that comes along that offers proof or supporting evidence to back that up, you're going to buy into, if it has the least error of credibility about it.\r\n(0:44:13)"}),(0,a.jsx)(t.p,{children:"How much did you say?\r\nTwenty-five. It's a bargain.\r\nIt's a bargain.\r\nWith all due respect to Stan, I think that he jumped on the MJ-12 documents because they so neatly packaged up and supported what he had already decided was true about Roswell. Philip Klass, who has been attacking the reality of flying saucers for several decades anyway, he noted that in this Cutler-Twining memo, the typeface was the large piketype.\r\n(0:44:56)"}),(0,a.jsx)(t.p,{children:"So he wrote me saying perhaps I hadn't noticed that, but the tradition at the White House and the National Security Council was the small elite type, and he had nine samples to prove it.\r\nAnd he challenged me to find any genuine letters, memos from the right people, right time frame, or a number of conditions, done in the same size and style type.\r\nHe offered me $100 each for every genuine such item, with a limit, unfortunately, of $10. And I sent him $20 just to tease him. He accepted $2. I think he thought he was home free.\r\n(0:45:31)"}),(0,a.jsx)(t.p,{children:"Once I got back from the Eisenhower Library, I sent him another $14, and an invoice for $1,000. And he paid me.\r\nHere's the crazy part, though.\r\nHe'd never been to the Eisenhower Library. They have 250,000 pages of National Security Council material.\r\nTo generalize from nine to 250,000 is absurd.\r\nIt's typical of the intellectual bankruptcy of the pseudoscience of anti-euphology. Find something to grab on to, and who cares whether it's right or not?\r\n(0:46:07)"}),(0,a.jsx)(t.p,{children:"Stanton's been attacked almost unmercifully over the Roswell thing, which he continues to promote.\r\nMight be that Stanton will turn out to be right down the road, and everybody else is wrong.\r\nBut Stanton gets the word out there, and a lot of people in the world know about euphology because of Stanton. Right, wrong, or indifferent. People know that Stanton's out there, and he's looking, and he believes.\r\n(0:46:34)"}),(0,a.jsx)(t.p,{children:"You can't make an omelet without breaking eggs. Have I pleased everybody? I certainly have not.\r\n(0:46:42)"}),(0,a.jsx)(t.hr,{}),(0,a.jsx)(t.p,{children:"That's the price you pay.\r\nI had a father-in-law who said, when you're playing bridge, if you don't get set once in a while, you're not bidding high enough.\r\nSo if you can't stand the heat, as Harry Truman said, get out of the kitchen.\r\nI can stand the heat, and I will continue to do it as long as I can.\r\nAnd I hope my kids will appreciate that I've made a real effort to educate lots of people.\r\n(0:47:11)"}),(0,a.jsx)(t.p,{children:"With A, a concern about how do you get at truth.\r\nB, a willingness to stand up and be counted when you've done your homework.\r\nAnd C, a recognition of how important it is, if you can do something, that helps society to do it.\r\nDon't hold back.\r\nDo I think the world is a better place for my contribution to it?\r\nTough question. I'd say yes.\r\n(0:47:40)"}),(0,a.jsx)(t.p,{children:"How do you measure it? I don't know.\r\nWho speaks for planet Earth? There is a challenge.\r\nI don't know who it should be.\r\nBut I think we do need to start acting like grown-ups instead of spoiled brats.\r\nSee, on a bad day, maybe we can qualify for admission to the Cosmic Preschool. Thank you very much for listening. I'll be signing books outside.\r\nThank you.\r\n(0:49:22)"})]}),"\n",(0,a.jsx)(t.p,{children:"(2025-02-03)"})]})}function u(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>i});var o=n(296540);const a={},r=o.createContext(a);function s(e){const t=o.useContext(r);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(r.Provider,{value:t},e.children)}},554108:e=>{e.exports=JSON.parse('{"permalink":"/ds/en/blog/2025/02/03/stan_friedman_home","source":"@site/blog/2025-02-03-stan_friedman_home.md","title":"\u52d5\u753b\uff1aStanton Friedman \u306e \u66f8\u658e\uff0b\u8cc7\u6599\u5eab \u306e\u69d8\u5b50","description":"\u524d\u7f6e\u304d","date":"2025-02-03T00:00:00.000Z","tags":[{"inline":false,"label":"UFO","permalink":"/ds/en/blog/tags/UFO","description":"UFO \u95a2\u9023"},{"inline":false,"label":"2025-01","permalink":"/ds/en/blog/tags/2025-01","description":"2025-01"}],"readingTime":38.67,"hasTruncateMarker":true,"authors":[],"frontMatter":{"tags":["UFO","2025-01"]},"unlisted":false,"prevItem":{"title":"Bruce Greyson : \u8abf\u67fb\u306b\u3088\u308c\u3070\u3001\u79d1\u5b66\u8005\u306e\u534a\u6570\u306f\u5fc3\u3068\u8133\u306f\u5225\u306e\u3082\u306e\u3067\u3001\u5fc3\u306f\u8133\u306e\u7523\u7269\u3067\u306f\u306a\u3044\u3068\u8003\u3048\u3066\u3044\u308b","permalink":"/ds/en/blog/2025/02/03/half_percent_greyson_einstein"},"nextItem":{"title":"Bill Mcclure : \u81ea\u8eab\u306e abduction \u4f53\u9a13\u3092\u8a9e\u308b","permalink":"/ds/en/blog/2025/02/02/bill_mcclure"}}')}}]);